import { Context } from '@temporalio/activity';
import { s3Client } from '../services/s3';
import { db } from '../services/db';

export async function exportUserDataActivity(input: {
  targetUserId: string;
  initiatorUserId: string;
  destinationBucket: string;
}): Promise<{ s3Uri: string }> {
  const { targetUserId, initiatorUserId, destinationBucket } = input;

  const initiator = await db.query('SELECT role FROM users WHERE id = $1', [initiatorUserId]);
  const isSelf = targetUserId === initiatorUserId;
  const isDPO = initiator.rows[0]?.role === 'DATA_PROTECTION_OFFICER';
  if (!isSelf && !isDPO) {
    throw new Error('Forbidden: initiator lacks permission to export data for target user');
  }

  const profile = await db.query('SELECT * FROM users WHERE id = $1', [targetUserId]);
  const paymentMethods = await db.query('SELECT * FROM payment_tokens WHERE user_id = $1', [targetUserId]);
  const orders = await db.query('SELECT * FROM customer_orders WHERE user_id = $1', [targetUserId]);

  const dump = JSON.stringify({ profile: profile.rows[0], paymentMethods: paymentMethods.rows, orders: orders.rows });
  const s3Key = `exports/${targetUserId}/full_data_${Date.now()}.json`;

  await s3Client.putObject({
    Bucket: destinationBucket,
    Key: s3Key,
    Body: dump,
    ContentType: 'application/json'
  });

  return { s3Uri: `s3://${destinationBucket}/${s3Key}` };
}
